<?php
declare(strict_types=1); require_once __DIR__.'/_automation.php'; require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $a=$_POST['action']??''; if($a==='generate') { $id=generate_one_draft(); flash($id?'Draft generated.':'No draft generated; check limits/logs.'); } if($a==='render') flash('Rendered '.render_approved_drafts().' draft(s).'); if($a==='publish') flash('Published '.publish_ready_drafts().' draft(s).'); redirect('dashboard.php'); }
$stats=['active_products'=>db()->query('SELECT COUNT(*) FROM products WHERE active=1')->fetchColumn(),'active_campaigns'=>db()->query('SELECT COUNT(*) FROM campaigns WHERE active=1')->fetchColumn(),'needs_review'=>db()->query("SELECT COUNT(*) FROM drafts WHERE status='needs review'")->fetchColumn(),'ready'=>db()->query("SELECT COUNT(*) FROM drafts WHERE status='rendered'")->fetchColumn()];
$errors=db()->query("SELECT * FROM logs WHERE level IN ('error','warning') ORDER BY id DESC LIMIT 5")->fetchAll(); $drafts=db()->query('SELECT d.*, p.name product FROM drafts d JOIN products p ON p.id=d.product_id ORDER BY d.id DESC LIMIT 8')->fetchAll();
layout_header('Dashboard'); show_flash(); ?><div class="grid"><?php foreach($stats as $k=>$v): ?><div class="card"><div class="muted"><?=h(ucwords(str_replace('_',' ',$k)))?></div><div class="stat"><?=h((string)$v)?></div></div><?php endforeach; ?></div><form method="post" class="actions"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><button name="action" value="generate">Generate draft now</button><button name="action" value="render" class="secondary">Render approved drafts</button><button name="action" value="publish" class="secondary" data-confirm="Publish rendered drafts to Instagram?">Publish ready drafts</button><a class="btn light" href="logs.php">View logs</a></form><div class="split"><section class="panel"><h2>Recent generated drafts</h2><div class="table-wrap"><table><tr><th>ID</th><th>Product</th><th>Status</th><th>Hook</th><th>Created</th></tr><?php foreach($drafts as $d): ?><tr><td><a href="drafts.php?id=<?=$d['id']?>">#<?=$d['id']?></a></td><td><?=h($d['product'])?></td><td><?=render_status_badge($d['status'])?></td><td><?=h($d['hook_text'])?></td><td><?=h($d['created_at'])?></td></tr><?php endforeach; ?></table></div></section><section class="panel"><h2>Recent publish/errors</h2><?php foreach($errors as $e): ?><p><b><?=h($e['level'])?></b> <?=h($e['message'])?><br><span class="small muted"><?=h($e['created_at'])?></span></p><?php endforeach; ?></section></div><?php layout_footer();
